    # --- Step 1: Build the nested dictionary structure from the flat list ---
    tree = {}
    for item in value:
        if hasattr(item, 'get') and item.get('fullPath'):
            parts = item['fullPath'].split('/')[1:]

            if len(parts) >= 3:
                site_name, area_name, line_name = parts[0], parts[1], parts[2]

                if site_name not in tree:
                    tree[site_name] = {"label": site_name, "expanded": True, "data": {"type": "Site"}, "items": {}}
                site_node = tree[site_name]

                if area_name not in site_node["items"]:
                    site_node["items"][area_name] = {"label": area_name, "expanded": True, "data": {"type": "Area"}, "items": {}}
                area_node = site_node["items"][area_name]

                area_node["items"][line_name] = {"label": line_name, "expanded": False, "data": {"fullPath": item['fullPath'], "type": "Line"}, "items": []}

    # --- Step 2: Convert the nested dictionaries into sorted lists for the tree component ---
    def convert_and_sort(node):
        if isinstance(node.get("items"), dict):
            item_list = sorted(node["items"].values(), key=lambda x: x['label'])
            node["items"] = item_list
            for child in node["items"]:
                convert_and_sort(child)
        return node

    temp_root = {"items": tree}
    convert_and_sort(temp_root)
    final_tree = temp_root['items']

    # --- Step 3: Recursively populate parent data fields with child tag paths ---
    def populate_data_fields(node):
        if not node.get("items"):
            return [node["data"]["fullPath"]]

        all_descendant_paths = []
        for child in node["items"]:
            paths_from_child = populate_data_fields(child)
            all_descendant_paths.extend(paths_from_child)

        all_descendant_paths.sort()
        node["data"]["fullTagPaths"] = all_descendant_paths
        return all_descendant_paths

    for site_node in final_tree:
        populate_data_fields(site_node)

    # --- Step 4: NEW - Wrap the result in a top-level "Enterprise" object ---
    all_tag_paths = []
    # Collect all paths from each site's data field
    for site in final_tree:
        if 'fullTagPaths' in site['data']:
            all_tag_paths.extend(site['data']['fullTagPaths'])

    # Sort the final combined list
    all_tag_paths.sort()

    # Build the final structure you requested
    enterprise_wrapper = [{
        "label": "Enterprise",
        "expanded": True,
        "data": {
            "fullTagPaths": all_tag_paths
        },
        "items": final_tree
    }]

    return enterprise_wrapper

